using System.Collections.ObjectModel;using System.Windows.Input;using WAID.Application.Services;namespace WAID.Desktop.ViewModels;public sealed record PerformanceMetricCard(string Name,string Value,string Quality,string Summary);public sealed class PerformanceHistoryViewModel:ViewModelBase
{private readonly PerformanceHistoryService _service;private PerformanceMetricKind _kind=PerformanceMetricKind.CpuUtilization;private MetricResolution _resolution=MetricResolution.Hourly;private int _days=7;private string _status="Collect metrics, then build rollups to view history.";private string _summary="No history loaded.";private string _comparison="Comparison unavailable.";
 public PerformanceHistoryViewModel(PerformanceHistoryService service){_service=service;CollectCommand=new AsyncCommand(CollectAsync);RefreshCommand=new AsyncCommand(RefreshAsync);CompareCommand=new AsyncCommand(CompareAsync);}public ObservableCollection<PerformanceMetricRollup>Points{get;}=[];public ObservableCollection<SustainedMetricChange>Changes{get;}=[];public ObservableCollection<PerformanceMetricCard>Cards{get;}=[];public IReadOnlyList<PerformanceMetricKind>Kinds{get;}=Enum.GetValues<PerformanceMetricKind>();public IReadOnlyList<MetricResolution>Resolutions{get;}=[MetricResolution.Hourly,MetricResolution.Daily,MetricResolution.Weekly];public ICommand CollectCommand{get;}public ICommand RefreshCommand{get;}public ICommand CompareCommand{get;}public PerformanceMetricKind SelectedKind{get=>_kind;set=>Set(ref _kind,value);}public MetricResolution SelectedResolution{get=>_resolution;set=>Set(ref _resolution,value);}public int Days{get=>_days;set=>Set(ref _days,Math.Clamp(value,1,365));}public string Status{get=>_status;private set=>Set(ref _status,value);}public string AccessibleSummary{get=>_summary;private set=>Set(ref _summary,value);}public string Comparison{get=>_comparison;private set=>Set(ref _comparison,value);}
 public async Task LoadAsync()=>await RefreshAsync();private async Task CollectAsync(){try{var samples=await _service.CollectAsync(CancellationToken.None);await _service.BuildRollupsAsync(DateTimeOffset.UtcNow.AddDays(-365),CancellationToken.None);Cards.Clear();foreach(var group in samples.GroupBy(x=>x.Kind)){var latest=group.Last();Cards.Add(new(group.Key.ToString(),latest.Value is null?"Unavailable":$"{latest.Value:F1} {latest.Unit}",latest.Quality.ToString(),latest.Detail??latest.Source));}Status=$"Collected {samples.Count} local metrics and rebuilt versioned rollups.";await RefreshAsync();}catch(Exception){Status="Performance metrics could not be collected or stored. Check database health and Logs & Audit.";}}
 private async Task RefreshAsync(){try{var to=DateTimeOffset.UtcNow;var result=await _service.QueryAsync(new(SelectedKind,to.AddDays(-Days),to,SelectedResolution,300),CancellationToken.None);Points.Clear();Changes.Clear();foreach(var x in result.Points)Points.Add(x);foreach(var x in result.Changes)Changes.Add(x);AccessibleSummary=result.AccessibleSummary;Status=$"Showing {result.Points.Count} stored points at {SelectedResolution} resolution. Missing data remains explicit.";}catch(Exception){Status="Performance history is unavailable. Collect metrics or check database health.";}}
 private async Task CompareAsync(){var now=DateTimeOffset.UtcNow;var length=TimeSpan.FromDays(Days);var result=await _service.CompareAsync(SelectedKind,now-length-length,now-length,now-length,now,CancellationToken.None);Comparison=result.Summary;}}
